package tui

// commandExamples and commandNotes feed /help, /help COMMAND and the "/" menu, in the active language.
func (app *Interface) commandExamples() map[string]string {
	group := app.Service.L("pruebas", "tests")
	return map[string]string{"motion": "/motion tap 0.5 0.5 @all", "settings": "/settings", "devices": "/devices", "doctor": "/doctor", "rename": app.Service.L("/rename DEV-003 Caja-1", "/rename DEV-003 Box-1"), "group": "/group create " + group + " @DEV-001,DEV-002", "apk": `/apk C:\apks\app.apk @` + group, "apps": "/apps @DEV-001", "start": "/start com.android.settings @all", "stop": "/stop com.android.settings @all", "url": "/url https://example.com @" + group, "text": app.Service.L("/motion text Hola, mañana 😊 @DEV-001", "/motion text Hello, tomorrow 😊 @DEV-001"), "key": "/motion key HOME @all", "push": `/push C:\datos\a.txt /sdcard/Download/ @` + group, "shell": "!getprop ro.product.model", "tap": "/motion tap 0.5 0.5 @" + group, "swipe": "/motion swipe 0.5 0.8 0.5 0.2 400 @" + group, "screenshot": "/screenshot @all", "wait": "/wait 1000 @all", "routine": "/routine setup @all", "jobs": "/jobs", "retry": "/retry", "sync": "/sync start DEV-001 DEV-002 DEV-003", "view": "/view @all", "copy": "/copy", "clear": "/clear", "help": "/help motion tap", "exit": "/exit", "uninstall": "/uninstall " + app.Service.L("com.ejemplo.app", "com.example.app") + " @" + group, "wipe": "/wipe com.android.chrome @" + group, "pull": "/pull /sdcard/Download/ @DEV-001", "reboot": "/reboot @" + group, "wifi": "/wifi off @all", "rotation": "/rotation 90 @all", "resolution": "/resolution 1080x1920 @all", "android-setting": "/android-setting global stay_on_while_plugged_in 7 @all", "perm": "/perm grant com.android.chrome android.permission.CAMERA @" + group, "logcat": "/logcat 500 @DEV-001", "record": "/record 10 @DEV-001"}
}
func (app *Interface) commandNotes() map[string]string {
	return map[string]string{"settings": app.Service.L("↑↓ elige un ajuste; Enter edita y confirma; Esc vuelve. Idioma, concurrencia, tiempo, ventanas y CXT se guardan; el destino solo dura la sesión.", "↑↓ selects a setting; Enter edits and confirms; Esc returns. Language, concurrency, timeout, windows and CXT are saved; the target lasts only for the session."), "devices": app.Service.L("Espacio marca placas, enter las fija como destino, g crea un grupo con ellas, r renombra, s hace capturas. Las columnas muestran batería y temperatura; ! marca los avisos.", "Space marks devices, enter sets them as the target, g creates a group with them, r renames, s takes screenshots. The columns show battery and temperature; ! marks alerts."), "doctor": app.Service.L("Comprueba ADB, scrcpy, la clave CXT, el estado de cada placa y su batería y temperatura (límites en /settings). Úsalo si algo no responde.", "Checks ADB, scrcpy, the CXT key, the state of each device and its battery and temperature (limits in /settings). Use it when something does not answer."), "rename": app.Service.L("El alias se guarda en data/inventory.json y sigue a la placa por su número de serie.", "The alias is saved in data/inventory.json and follows the device by its serial number."), "group": app.Service.L("Los grupos guardan números de serie: siguen valiendo aunque cambies la placa de puerto USB. /group rename NOMBRE NUEVO les cambia el nombre sin tocar sus placas.", "Groups store serial numbers: they keep working if you move a device to another USB port. /group rename NAME NEW renames one without touching its devices."), "apk": app.Service.L("La ruta es de este PC. Tab completa carpetas y archivos .apk. Reinstala si ya existe. Una carpeta con varios .apk se instala junta (APK dividida).", "The path is on this PC. Tab completes folders and .apk files. Reinstalls if already there. A folder with several .apk files is installed together (split APK)."), "apps": app.Service.L("Lista las apps instaladas por el usuario; después /start y /stop autocompletan esos paquetes.", "Lists the apps installed by the user; afterwards /start and /stop complete those packages."), "text": app.Service.L("Admite acentos y emojis. Se escribe en el campo que tenga el foco en cada placa.", "Accents and emojis work. It is typed in the focused field of each device."), "key": app.Service.L("HOME inicio, BACK atrás, ENTER aceptar, RECENTS recientes, WAKEUP encender pantalla, POWER encendido, VOLUME_UP/VOLUME_DOWN volumen, DEL borrar, TAB, MENU, CAMERA, o un código Android.", "HOME home, BACK back, ENTER enter, RECENTS recent apps, WAKEUP screen on, POWER power, VOLUME_UP/VOLUME_DOWN volume, DEL delete, TAB, MENU, CAMERA, or an Android key code."), "push": app.Service.L("Copia un archivo de este PC a la ruta indicada en cada placa.", "Copies a file from this PC to the given path on each device."), "shell": app.Service.L("Ejecuta la orden tal cual en cada placa. Úsala con cuidado: no hay deshacer.", "Runs the command as is on each device. Use it with care: there is no undo."), "tap": app.Service.L("Las coordenadas van de 0 a 1 (0.5 0.5 es el centro), así valen para cualquier resolución.", "Coordinates go from 0 to 1 (0.5 0.5 is the center), so they work at any resolution."), "swipe": app.Service.L("Desliza de (X,Y) a (X2,Y2), en coordenadas 0..1, durante los milisegundos indicados (300 por defecto).", "Swipes from (X,Y) to (X2,Y2), in 0..1 coordinates, over the given milliseconds (300 by default)."), "screenshot": app.Service.L("Las capturas se guardan en output/screenshots con el alias y la hora.", "Screenshots are saved in output/screenshots with the alias and the time."), "routine": app.Service.L("Las rutinas son archivos JSON en routines/. Sus ${parámetros} se pasan como clave=valor; ${alias}, ${serial}, ${model} e ${index} los pone cada placa. Cada paso admite retry, onError (abort o continue) y timeout.", "Routines are JSON files in routines/. Their ${parameters} are given as key=value; ${alias}, ${serial}, ${model} and ${index} come from each device. Every step accepts retry, onError (abort or continue) and timeout."), "jobs": app.Service.L("Sin ID abre los lotes recientes; con ID muestra su detalle. Enter ve el detalle y r reintenta las fallidas. /job y /lotes son alias. Cada orden sobre placas crea un lote con su informe en output/logs/jobs.", "Without an ID opens recent batches; with an ID shows its details. Enter shows details and r retries failed devices. /job is an alias. Every command on devices creates a batch with its report in output/logs/jobs."), "retry": app.Service.L("Repite el lote sólo en las placas que fallaron. Sin ID usa el último lote.", "Repeats the batch only on the devices that failed. Without an ID it uses the last batch."), "sync": app.Service.L("Lo que hagas con ratón y teclado en la ventana de la principal se repite en las seguidoras.", "What you do with mouse and keyboard in the master window is repeated on the followers."), "view": app.Service.L("Cada ventana maneja su móvil; van en bloque (arrastra una y se mueven todas). --read-only para sólo mirar.", "Each window controls its device; they move as a block (drag one and they all move). --read-only to watch only."), "copy": app.Service.L("Copia como texto plano el último bloque de resultados; si es un lote, con toda su salida.", "Copies the last result block as plain text; for a batch, with its full output."),
		"uninstall":       app.Service.L("Quita la app y sus datos de cada placa. No hay deshacer: para volver, /apk la instala de nuevo.", "Removes the app and its data from each device. There is no undo: /apk installs it again."),
		"wipe":            app.Service.L("Borra datos, sesión y caché de la app; queda como recién instalada. No hay deshacer.", "Clears the app's data, session and cache; it is left as freshly installed. There is no undo."),
		"pull":            app.Service.L("Copia el archivo o la carpeta de cada placa a output/downloads/ALIAS, sin mezclar placas.", "Copies the file or folder of each device to output/downloads/ALIAS, keeping devices apart."),
		"reboot":          app.Service.L("Sin modo es un reinicio normal. Las placas se desconectan un rato y vuelven solas a la lista.", "Without a mode it is a normal reboot. The devices disconnect for a while and come back to the list by themselves."),
		"wifi":            app.Service.L("Si las placas usan ADB por Wi-Fi, apagarlo las desconecta.", "If the devices use ADB over Wi-Fi, turning it off disconnects them."),
		"resolution":      app.Service.L("Sin argumentos muestra la resolución y densidad de cada placa. ANCHOxALTO la fija (con DPI opcional) hasta que pongas reset, que vuelve a la física y conserva la densidad. Con todas iguales, los toques de /sync caen en el mismo botón; /sync ya las iguala solo mientras dura.", "Without arguments shows the resolution and density of each device. WIDTHxHEIGHT sets it (with an optional DPI) until reset, which goes back to the physical one and keeps the density. With all of them equal, /sync taps land on the same button; /sync already equalizes them while it lasts."),
		"rotation":        app.Service.L("auto vuelve a girar con el sensor; 0, 90, 180 o 270 fijan la orientación. Útil antes de una réplica.", "auto rotates with the sensor again; 0, 90, 180 or 270 lock the orientation. Useful before a replica."),
		"android-setting": app.Service.L("Equivale a settings put de Android. Las sugerencias muestran ajustes habituales y sus valores.", "Same as Android's settings put. The suggestions show common settings and their values."),
		"perm":            app.Service.L("Concede o retira permisos de ejecución sin tocar la pantalla. El permiso va con su nombre completo.", "Grants or revokes runtime permissions without touching the screen. The permission goes with its full name."),
		"logcat":          app.Service.L("Guarda las últimas líneas del registro de cada placa en output/logcat (500 por defecto).", "Saves the last log lines of each device to output/logcat (500 by default)."),
		"record":          app.Service.L("Graba hasta 180 segundos y guarda el vídeo en output/screenshots. El tiempo máximo por paso de /settings debe ser mayor.", "Records up to 180 seconds and saves the video to output/screenshots. The step timeout in /settings must be longer."),
	}
}
